from pt import *
items = [
 HDR(),
 H(r"## Appendix A. Formal definitions and random set theory", [90, 93, 373, 105]),
 T(r"""As a complement to Section 3, this section provides a formal description of $\epsilon$-RandUP using random set theory. Since the set estimator $\hat{\mathcal{Y}}^M_{\epsilon}$ in (2) is a random variable, describing its measurability properties is important to formally analyze its convergence properties (in an appropriate topology, which we define using the Hausdorff distance). In particular, random set theory provides a rigorous framework to characterize the probability distribution of $\hat{\mathcal{Y}}^M_{\epsilon}$ in Theorems 1 and 2.""", [89, 114, 523, 179]),
 T(r"""We denote $\mathcal{K}$ for the family of nonempty compact subsets of $\mathbb{R}^n$, $\mathcal{B}(\mathbb{R}^n)$ for the Borel $\sigma$-algebra for the Euclidean topology on $\mathbb{R}^n$ associated to the usual Euclidean norm $\|\cdot\|$, $\lambda(\cdot)$ for the Lebesgue measure over $\mathbb{R}^p$, $\mathrm{H}(A)$ for the convex hull of a subset $A\subset\mathbb{R}^n$, $\oplus$ for the Minkowski sum, $B(x,r)=\{y\in\mathbb{R}^n: \|y-x\|\leq r\}$ for the closed ball of center $x\in\mathbb{R}^n$ and radius $r\geq 0$, $\mathring{B}(x,r)$ for the open ball, and $\partial A$ for the boundary of any $A\subset\mathbb{R}^n$.""", [89, 181, 523, 248]),
 H(r"### A.1. Random set theory", [89, 263, 203, 274]),
 T(r"""Our analysis hinges on the observation that the set estimator $\hat{\mathcal{Y}}_\epsilon^M$ is a random compact set, i.e., $\hat{\mathcal{Y}}_\epsilon^M$ is a random variable taking values in the family of nonempty compact sets $\mathcal{K}$. To characterize the accuracy of our estimator, we use the *Hausdorff metric*, which is defined for any $A,B\in\mathcal{K}$ in (3) as""", [89, 282, 523, 321]),
 T(r"""$$
d_\mathrm{H}(A,B) = \max\big( \sup_{x\in B} \inf_{y\in A} \|x-y\|, \ \sup_{x\in A} \inf_{y\in B} \|x-y\| \big). \tag{5}
$$""", [176, 324, 527, 355]),
 T(r"""This metric induces the *myopic topology* on $\mathcal{K}$ (Molchanov, 2017) with its associated generated Borel $\sigma$-algebra $\mathcal{B}(\mathcal{K})$. $(\mathcal{K},\mathcal{B}(\mathcal{K}))$ is a measurable space, which motivates the following definition:""", [89, 356, 523, 382]),
 T(r"""**Definition 1 (Random compact set)** Let $(\Omega,\mathcal{G},\mathbb{P})$ be a probability space. A map $\hat{\mathcal{Y}}:\Omega\rightarrow\mathcal{K}$ is a random compact set if $\{\omega\in\Omega : \hat{\mathcal{Y}}(\omega)\in\mathscr{Y}\}\in\mathcal{G}$ for any $\mathscr{Y}\in\mathcal{B}(\mathcal{K})$.""", [89, 391, 523, 417]),
 T(r"""Since a random compact set $\hat{\mathcal{Y}}$ is a random variable with values in $\mathcal{K}$, its distribution is characterized by the probability $\mathbb{P}(\hat{\mathcal{Y}}\in\mathscr{Y})$ that it takes values in a measurable subset of compact sets $\mathscr{Y}\in\mathcal{B}(\mathcal{K})$. Equivalently (Molchanov, 2017), the law of $\hat{\mathcal{Y}}$ is characterized by the capacity functional $T_{\hat{\mathcal{Y}}}:\mathcal{K}\rightarrow[0,1]$, defined for any $K\in\mathcal{K}$ as $T_{\hat{\mathcal{Y}}}(K)= \mathbb{P}(\hat{\mathcal{Y}} \cap K\neq \emptyset)$. This functional describes the probability that $\hat{\mathcal{Y}}$ intersects any compact set $K$. We will analyze this functional to prove the convergence of our set estimator in Theorems 1 and 2.""", [89, 424, 523, 510]),
 T(r"""Our asymptotic convergence result in Theorem 1 relies on (Molchanov, 2017, Proposition 1.7.23), which provides sufficient conditions for the convergence of random closed sets. We restate this result in the particular case of a sequence of random compact sets.""", [89, 512, 523, 551]),
 T(r"""**Theorem 3 (Convergence of Random Sets to a Deterministic Limit (Molchanov, 2017))** Let $\mathcal{Y}\in\mathcal{K}$ and let $\{\hat{\mathcal{Y}}^M\}_{M=1}^\infty$ be a sequence of random compact sets. Assume that""", [89, 560, 523, 587]),
 T(r"""- For any $K\in\mathcal{K}$ such that $\mathcal{Y}\cap K=\emptyset$,""", [96, 593, 300, 605]),
 T(r"""$$
\mathbb{P}(\hat{\mathcal{Y}}^M\cap K \neq \emptyset \ \text{infinitely often}) = \mathbb{P}\left(\bigcap_{N=1}^\infty\bigcup_{M=N}^\infty \{\hat{\mathcal{Y}}^M\cap K \neq \emptyset\}\right) = 0. \tag{C1}
$$""", [147, 608, 528, 650]),
 T(r"""- For any open subset $G\subset\mathbb{R}^n$ such that $\mathcal{Y}\cap G \neq \emptyset$,""", [96, 656, 340, 668]),
 T(r"""$$
\mathbb{P}(\hat{\mathcal{Y}}^M\cap G = \emptyset \ \text{infinitely often}) = \mathbb{P}\left(\bigcap_{N=1}^\infty\bigcup_{M=N}^\infty \{\hat{\mathcal{Y}}^M\cap G = \emptyset\}\right) = 0. \tag{C2}
$$""", [148, 671, 528, 713]),
 PNUM(15),
]
page(15, items, r"""First appendix page. Text and mathematics taken from the authors' TeX (main.tex lines 1367-1460), macros expanded (\B -> \mathcal{B}, \G -> \mathcal{G}, \K -> \mathcal{K}, \mathscr{Y} kept), and compared with the 150-dpi render and a 220-dpi crop of the page from Section A.1 downwards. The three displays were extractor formula images and are now LaTeX with their printed tags: the Hausdorff metric restated as Eq. (5) (with '=' and a final period; the main-text version is Eq. (3) with ':='), and the two conditions of Theorem 3 tagged (C1) and (C2). Checked (C1): P(\hat Y^M cap K != empty infinitely often) = P(cap_{N=1}^inf cup_{M=N}^inf {\hat Y^M cap K != empty}) = 0 for any K in K with Y cap K = empty; (C2): same with an open G subset R^n, Y cap G != empty, and events {\hat Y^M cap G = empty}. Definition 1 (Random compact set) and the capacity functional T_{\hat Y}(K) = P(\hat Y cap K != empty) checked; the script letter for a measurable family of compact sets is \mathscr{Y}. Theorem 3's title is printed in bold including the citation '(Molchanov, 2017)'; label written '**Theorem 3 (Convergence of Random Sets to a Deterministic Limit (Molchanov, 2017))**' with the printed punctuation (no period), likewise '**Definition 1 (Random compact set)**', whose body is the single sentence pair up to 'for any Y in B(K).' as in the TeX environment. The theorem's two bulleted hypotheses are separate list-line items each followed by its display; the conclusion of Theorem 3 ('Then, the sequence ...') is on page 16. Headings fixed to '## Appendix A. ...' and '### A.1. Random set theory'. Cross references as printed: 'Section 3', '(2)', '(3)', 'Theorems 1 and 2'. Running header and page number 15 omitted.""")
